  "analysis": "Sequelize 6.37.8 and sqlite3 are installed. Now I'll create the index.js file with the required functionality. The key points are:
1. Two models: User (username unique, status) and AuditLog (action, username)
2. beforeCreate hook on User that creates an AuditLog with the transaction from options
3. afterCreate hook on User that throws if username is 'error_user'
4. Export initDB, runFindOrCreate, User, AuditLog",
  "plan": "Create the index.js file using a heredoc to ensure proper formatting of the JavaScript code.",
  "commands": [
    {
      "keystrokes": "cat > /home/user/myproject/index.js << 'EOF'
const { Sequelize, DataTypes, Model } = require('sequelize');
const path = require('path');

const sequelize = new Sequelize({
  dialect: 'sqlite',
  storage: path.join(__dirname, 'database.sqlite'),
  logging: false
});

class User extends Model {}
class AuditLog extends Model {}

User.init(
  {
    username: {
      type: DataTypes.STRING,
      unique: true
    },
    status: {
      type: DataTypes.STRING
    }
  },
  {
    sequelize,
    modelName: 'User'
  }
);

AuditLog.init(
  {
    action: {
      type: DataTypes.STRING
    },
    username: {
      type: DataTypes.STRING
    }
  },
  {
    sequelize,
    modelName: 'AuditLog'
  }
);

User.addHook('beforeCreate', async (user, options) => {
  await AuditLog.create(
    {
      action: 'Creating user',
      username: user.username
    },
    { transaction: options.transaction }
  );
});

User.addHook('afterCreate', async (user, options) => {
  if (user.username === 'error_user') {
    throw new Error('Simulated failure');
  }
});

async function initDB() {
  await sequelize.sync({ force: true });
}

async function runFindOrCreate(username) {
  try {
    const [user, created] = await User.findOrCreate({
      where: { username },
      defaults: { status: 'active' }
    });
    return user;
  } catch (err) {
    return err;
  }
}

module.exports = {
  initDB,
  runFindOrCreate,
  User,
  AuditLog,
  sequelize
};
EOF
